{
  "implementation": "def solve(case):
    initial = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']

    current_state = initial
    steps = []
    step = 0

    while step < max_steps:
        state_def = transitions[current_state]
        if state_def['kind'] == 'final':
            return {'final': state_def['value'], 'status': 'completed', 'trace': steps}
        action = state_def['action']
        obs = tool_obs[action]
        next_state = state_def['next_by_observation'].get(obs, state_def['default_next'])
        steps.append({
            'step': step,
            'action': action,
            'observation': obs,
            'state': next_state
        })
        current_state = next_state
        step += 1

    state_def = transitions[current_state]
    if state_def['kind'] == 'final':
        return {'final': state_def['value'], 'status': 'completed', 'trace': steps}
    else:
        return {'final': None, 'status': 'timeout', 'trace': steps}"
}
